// dz — རྫོང་ཁ (dzongkha).
//
// A chave é o TEXTO EM PORTUGUÊS, exatamente como aparece no código. O que faltar aqui aparece em
// português, e não como tela vazia.
//
// POR QUE ENTROU: é a língua nacional do BUTÃO (Constituição de 2008, art. 1), e o Butão era o último dos
// membros da ONU alcançáveis que nenhuma língua do Syden alcançava. Entrou a pedido do Sydenstricker, em
// 04/10/2026, sabendo da confiança: "é melhor o feito do que o perfeito".
//
// ===================================================================================================
// CONFIANÇA: BAIXA PARA MÉDIA — a mais baixa de todos os dicionários do Syden, e é por isso que este
// cabeçalho é longo. Quem ler dzongkha e achar uma frase estranha, a troca é de uma linha.
//
// O QUE VEIO DE PESQUISA (04/10/2026), e por isso é o mais seguro do arquivo:
//   - tradução do MediaWiki para o dzongkha (languages/i18n/dz.json): ནང་བསྐྱོད། (entrar), ཕྱིར་བསྐྱོད།
//     (sair), ཆ་མེད་གཏང་། (cancelar), བཏོན་གཏང་། (apagar), འཚོལ་ཞིབ། (buscar), རྩིས་ཐོ། (conta),
//     ཡིག་སྣོད། (arquivo), ཞུན་དག (editar), གྲོགས་རམ། (ajuda), སྟོན། / སྦ། (mostrar / esconder);
//   - tradução do GTK e do painel de configurações do GNOME, feita pelo projeto Dzongkha Linux:
//     ཁ་བསྡམས། (fechar), སྲུངས། (salvar), ཁ་ཕྱེ། (abrir), ཁ་སྐོང་། (adicionar), རྩ་བསྐྲད་གཏང་། (remover),
//     འདྲ་བཤུས། (copiar), སྦྱར། (colar), ཆོག་ཡིག (senha), གསལ་གཞི (tela), བརྡ་བསྐུལ (notificação),
//     གློག་འཕྲིན (e-mail), སྒྲ (som), ལྡེ་སྒྲོམ (teclado), འབྱུང་སྣང (aparência), རྒྱབ་གཞི (fundo),
//     སྔོན་སྒྲིག (padrão), འཛོལ་བ (erro), ཚོས་གཞི (cor), ཡིག་གཟུགས (fonte), བརྟག་ཞིབ (teste).
// O RESTO É ESCOLHA MINHA, com base no tibetano escrito, que o dzongkha compartilha. As frases longas
// foram mantidas curtas e diretas de propósito: frase simples errada é fácil de consertar; frase
// elaborada errada não.
// ===================================================================================================
//
// TERMO TÉCNICO SEM PALAVRA PRÓPRIA vai TRANSLITERADO do inglês, que é como o dzongkha faz (o próprio GTK
// escreve ཌེཀསི་ཊོཔ། para "desktop"): མའི་ཀོ་ཕོན (microfone), ཀེ་མ་ར (câmera), སར་བར (servidor), བརའུ་ཟར
// (navegador), ཨིན་ཊར་ནེཊ (internet), ཨི་མོ་ཇི (emoji).
//
// ESCRITA: tibetana, SEM ESPAÇO ENTRE PALAVRAS — a sílaba se separa pelo tsheg (་) e a frase acaba no shad
// (།). A fonte de reserva é a Noto Serif Tibetan (não existe Sans).
//
// TOM: ཁྱོད, o "você" comum. GÊNERO: o dzongkha não tem gênero gramatical, e o verbo não diz o sexo.
//
// NÚMEROS: a numeração da escrita é a tibetana (༡༢༣). Número CONTADO numa frase vai em algarismo tibetano
// (༥ ཆུ་ཚོད, ༡༥); identificador TÉCNICO (1080p, 512 KB, 128×128, 1.21) fica em latino, como no fa.ts. E o
// Chrome não tem dados do dzongkha: os algarismos da tela vêm de web/src/algarismos.ts.
//
// {nome}: a partícula de caso muda conforme a última letra da palavra (གི / ཀྱི / གྱི / འི), e um campo
// não sabe qual é a dele. Então {nome} vem depois de dois-pontos, sem partícula colada.
//
// VOCABULÁRIO, decidido uma vez: comunidade = མི་སྡེ, canal = བརྒྱུད་ལམ, sala = ཁང་མིག, sala de voz =
// སྐད་ཀྱི་ཁང་མིག, chamada = ཁ་པར, conversa = གཏམ་གླེང, mensagem = འཕྲིན་ཡིག, lixeira = གད་སྙིགས་སྣོད,
// tópico = གླེང་རིམ, administrador = འཛིན་སྐྱོང་པ, dono = བདག་པོ, cargo = འགན་ཁུར, convite = མགྲོན་འབོད,
// perfil = ངོ་སྤྲོད, transmissão = བརྒྱུད་སྤེལ, membro = འཐུས་མི, pacote = ཐུམ་སྒྲིལ, enquete = འདྲི་དཔྱད,
// denúncia = ཞུ་གཏུག, vila = གྲོང་གསེབ, recado = བརྡ་ཁྱབ, configurações = སྒྲིག་སྟངས.
//
// SOM E VOZ SÃO DUAS PALAVRAS: སྐད é a voz, སྒྲ é o som de soundboard e de aviso.
//
// SELO E INSÍGNIA SEPARADOS: selo = ཐམ་ག (o da comunidade), insígnia = རྟགས་མ (a da pessoa).

