  'Desligado, a transmissão de quem está na sala aparece como convite e só começa a ser baixada quando você clica em Assistir. Isso poupa internet e processador — principalmente em sala cheia.':
    'ཁ་བསྡམས་པ་ཅིན་ ཁང་མིག་ནང་གི་བརྒྱུད་སྤེལ་ཚུ་ མགྲོན་འབོད་བཟུམ་སྦེ་སྟོན་འོང་། ཁྱོད་ཀྱིས་ བལྟ་ ཨེབ་པ་ཅིན་རྐྱངམ་ཅིག་ ཕབ་ལེན་འགོ་བཙུགས་འོང་། འདི་གིས་ ཨིན་ཊར་ནེཊ་དང་ ལས་སྣོན་ཆས་ཀྱི་ནུས་ཤུགས་ཉུང་སུ་བཟོཝ་ཨིན།',
