  'Efeitos visuais na chamada': 'ཁ་པར་ནང་གི་མཐོང་སྣང་ཕན་འབྲས།',
  'Em branco: fica até você apagar.': 'སྟོངམ: ཁྱོད་ཀྱིས་མ་བཏོན་ཚུན་ལུས་འོང་།',
