  'Endereço': 'ཁ་བྱང་།',
  'Endereço guardado. Confira a sua caixa de entrada para confirmar.': 'ཁ་བྱང་སྲུངས་ཡི། ངེས་དཔྱད་འབད་ནི་ལུ་ ཁྱོད་ཀྱི་འཕྲིན་སྒམ་ལུ་བལྟ།',
  'Endereço guardado. O envio de e-mail ainda não está ligado neste servidor, então o link de confirmação ficou no registro do servidor.':
    'ཁ་བྱང་སྲུངས་ཡི། སར་བར་འདི་ནང་ གློག་འཕྲིན་གཏང་ནི་ ད་ལྟོ་ཁ་མ་ཕྱེ་བས། དེ་འབདཝ་ལས་ ངེས་དཔྱད་འབྲེལ་ལམ་འདི་ སར་བར་གྱི་ཐོ་ཡིག་ནང་ལུས་ཡི།',
