  'Escolha aqui a língua do Syden. Vale na hora, só para você, e fica guardada neste computador.':
    'Syden གི་སྐད་ཡིག་ ནཱ་ལུ་གདམ། ཕྱིར་སྦེ་ ཁྱོད་རྐྱངམ་གཅིག་གི་དོན་ལུ་ནུས་ཅན་འགྱོཝ་ཨིན། གློག་རིག་འདི་ནང་སྲུངས་འོང་།',
