  'O sorteio de {premio} terminou sem participantes.': '{premio} གི་ཤོ་ལོ་ བཅའ་མར་གཏོགས་མི་མེད་པར་མཇུག་བསྡུ་ཡི།',
  'O Syden anuncia o prêmio no canal, e quem quiser participar reage com 🎉. Na hora marcada, ele sorteia entre quem reagiu e publica o resultado.': 'Syden གིས་ རྒྱུ་ལམ་ནང་ བྱ་དགའ་གསལ་བསྒྲགས་འབདཝ་ད་ བཅའ་མར་གཏོགས་ནི་ཡོད་མི་གིས་ 🎉 གིས་ལན་འདེབས་འབད། དུས་ཚོད་ལུ་ ལན་འདེབས་འབད་མི་ཚུ་གི་ནང་ལས་ ཤོ་ལོ་བཀལ་ཏེ་ གྲུབ་འབྲས་བཙུགས།',
