  'Canal dos parabéns': 'བཀྲ་ཤིས་བདེ་ལེགས་ཀྱི་རྒྱུ་ལམ',
  'Dia': 'ཚེས',
  'Hoje é aniversário de {pessoa}! 🎉 Parabéns!': 'ད་རིས་ {pessoa} གི་སྐྱེས་ཚེས་ཨིན! 🎉 བཀྲ་ཤིས་བདེ་ལེགས!',
  'Mês': 'ཟླ་བ',
  'No dia do aniversário de quem informou a data, o Syden publica os parabéns no canal escolhido. Use {pessoa} no lugar do nome.': 'ཚེས་གྲངས་བཙུགས་མི་གི་སྐྱེས་ཚེས་ཉིན་ Syden གིས་ གདམ་ཁ་རྐྱབ་མི་རྒྱུ་ལམ་ནང་ བཀྲ་ཤིས་བདེ་ལེགས་བཙུགས། མིང་གི་ཚབ་ལུ་ {pessoa} ལག་ལེན་འཐབ།',
  'Só o dia e o mês, nunca o ano. As comunidades que avisam aniversários dão os parabéns no dia. É opcional, e dá para apagar quando quiser.': 'ཚེས་དང་ཟླ་བ་རྐྱངམ་ཅིག ལོ་ནམ་ཡང་མེན། སྐྱེས་ཚེས་གསལ་བསྒྲགས་འབད་མི་མི་སྡེ་ཚུ་གིས་ ཉིན་དེ་ར་ བཀྲ་ཤིས་བདེ་ལེགས་ཞུ། གདམ་ཁ་ཨིན་ ནམ་ར་འབད་རུང་ བཏོན་ཚུགས།',
  'Texto dos parabéns': 'བཀྲ་ཤིས་བདེ་ལེགས་ཀྱི་ཡིག་ཐོག',
  'Agendar': 'དུས་འཆར་བཀོད',
