  'Combinado: lembro você em {tempo}.': 'འགྲིག: {tempo} ཤུལ་ལས་ དྲན་སྐུལ་འབད་གེ།',
  'Lembrar de mim': 'ང་ལུ་དྲན་སྐུལ་འབད',
  'Lembrar de mim em…': 'ང་ལུ་དྲན་སྐུལ་འབད…',
