  'Mensagens agendadas': 'དུས་འཆར་བཀོད་ཡོད་པའི་འཕྲིན་དོན',
  'Na hora marcada, o Syden publica o texto no canal. Dá para repetir todo dia ou toda semana.': 'གཏན་འཁེལ་འབད་མི་དུས་ཚོད་ནང་ Syden གིས་ ཡིག་ཐོག་ རྒྱུ་ལམ་ནང་བཙུགས་འོང་། ཉིན་བསྟར་ ཡང་ན་ བདུན་ཕྲག་བསྟར་ ལོག་འབད་ཚུགས།',
