  'Uma vez': 'ཚར་གཅིག',
  'Alguém escreve o comando no começo de uma mensagem, como !regras, e o Syden responde no canal com o texto que você cadastrar. Use {pessoa} para o nome de quem pediu e {comunidade} para o nome da comunidade.': 'མི་ཅིག་གིས་ འཕྲིན་དོན་གྱི་འགོ་ལུ་ !regras བཟུམ་གྱི་བཀོད་རྒྱ་བྲིས་པ་ཅིན་ ཁྱོད་ཀྱིས་བཙུགས་མི་ཡིག་ཐོག་ལས་ Syden གིས་ རྒྱུ་ལམ་ནང་ལན་སློག། ཞུ་མི་གི་མིང་ལུ་ {pessoa} དང་ མི་སྡེའི་མིང་ལུ་ {comunidade} ལག་ལེན་འཐབ།',
