  'Você recebeu uma advertência em {comunidade}: {motivo}': '{comunidade} ནང་ ཉེན་བརྡ་ཐོབ་ཡི: {motivo}',
  'Barrar excesso de mensagens (mais de 5 em 10 segundos)': 'འཕྲིན་དོན་ལྷག་པ་བཀག (སྐར་ཆ་ ༡༠ ནང་ ༥ ལས་ལྷག)',
  'Bloquear links nas mensagens': 'འཕྲིན་དོན་ནང་གི་ འབྲེལ་ལམ་བཀག',
  'Desligado': 'བསྡམས་ཡོད',
  'Modo lento': 'དལ་བའི་ཐབས་ལམ',
  'Modo lento de {canal}': '{canal} གི་དལ་བའི་ཐབས་ལམ',
  'Modo lento: uma mensagem a cada {tempo}.': 'དལ་བའི་ཐབས་ལམ: {tempo} རེ་ལུ་ འཕྲིན་དོན་གཅིག།',
  'Palavras proibidas': 'བཀག་ཡོད་པའི་ཚིག',
  'Quanto tempo cada pessoa espera entre uma mensagem e outra no canal.': 'རྒྱུ་ལམ་ནང་ འཕྲིན་དོན་བར་ན་ མི་རེ་རེ་གིས་ སྒུག་དགོ་པའི་དུས་ཡུན།',
  'Regras': 'སྒྲིག་གཞི',
  'Regras que o Syden aplica sozinho, antes de a mensagem aparecer. Quem administra não passa por elas. A mensagem barrada volta para quem escreveu, com o motivo, e ninguém mais a vê.': 'འཕྲིན་དོན་མ་ཐོན་པའི་ཧེ་མ་ Syden གིས་ རང་བཞིན་གྱིས་ ལག་ལེན་འཐབ་པའི་ སྒྲིག་གཞི། འཛིན་སྐྱོང་པ་ལུ་ མ་ཕོག། བཀག་པའི་འཕྲིན་དོན་ རྒྱུ་མཚན་དང་ཅིག་ཁར་ བྲིས་མི་ལུ་ལོག་འོང་། མི་གཞན་གྱིས་ མ་མཐོང་།',
  'Salvo.': 'སྲུང་བཞག་འབད་ཡི།',
  'Uma por linha. Vale a palavra inteira, sem diferença de acento ou de maiúscula: proibir uma palavra não barra outra mais longa que só a contenha.': 'གྲལ་ཐིག་རེ་ལུ་གཅིག། ཚིག་ཧྲིལ་པོ་རྩིས་འབདཝ་ཨིན: ཚིག་ཅིག་བཀག་ན་ དེ་ཚུད་པའི་ཚིག་རིངམོ་ཅིག་ མི་བཀག།',
  '{faltam} pontos para o nível {proximo}.': 'རིམ་པ་ {proximo} ལུ་ སྐར་ཚད་ {faltam} ལྷག་ཡོད།',
  'Adicionar recompensa': 'བྱ་དགའ་ཁ་སྐོང་རྐྱབ',
  'Cada mensagem vale pontos (uma por minuto), e cada minuto numa sala com mais alguém também. Quem sobe de nível recebe um aviso só para si.': 'འཕྲིན་དོན་རེ་རེ་ལུ་ སྐར་ཚད་ཐོབ་ (སྐར་མ་རེ་ལུ་ གཅིག)། མི་གཞན་དང་གཅིག་ཁར་ ཁང་མིག་ནང་ སྐར་མ་རེ་རེ་ལུ་ཡང་ ཐོབ། རིམ་པ་ཡར་སོང་མི་ལུ་ རང་རྐྱངམ་ཅིག་ལུ་ བརྡ་བསྐུལ་འོང་།',
  'Cargo da recompensa': 'བྱ་དགའི་ལཱ་འགན',
  'Crie um cargo acima para usar como recompensa.': 'བྱ་དགའ་སྦེ་ལག་ལེན་འཐབ་ནི་ལུ་ གོང་ལུ་ ལཱ་འགན་ཅིག་བཟོ།',
  'Escolha o cargo': 'ལཱ་འགན་གདམ',
