  'Você ainda não tem pontos aqui. Converse ou entre numa sala com alguém.': 'ནཱ་ལུ་ སྐར་ཚད་ད་ལྟོ་མེད། གཏམ་བཤད་ ཡང་ན་ མི་ཅིག་དང་གཅིག་ཁར་ ཁང་མིག་ནང་འཛུལ།',
