  'Cargos dão nome e cor a grupos de pessoas: "Veterano", "Turma da raide". Não mudam o que cada um pode fazer na comunidade.': 'ལཱ་འགན་གྱིས་ མི་ཚོགས་ལུ་ མིང་དང་ཚོས་གཞི་བྱིནམ་ཨིན: "རྒན་རིམ", "ལྷགས་རྒོལ་སྡེ་ཚན"། མི་སྡེ་ནང་ ག་གིས་ག་ཅི་འབད་ཚུགས་ག་ མ་སོར།',
