  'Notificações na área de trabalho': 'ཌེཀསི་ཊོཔ་ནང་གི་བརྡ་བསྐུལ།',
  'Nova conversa': 'གཏམ་གླེང་གསརཔ།',
  'Nova conversa em grupo': 'སྡེ་ཚན་གཏམ་གླེང་གསརཔ།',
