  'Os outros idiomas': 'སྐད་ཡིག་གཞན་ཚུ།',
  'Os outros passam a ouvir o efeito na hora. Você continua sem se escutar.': 'གཞན་མི་ཚུ་གིས་ ཕན་འབྲས་ཕྱིར་སྦེ་ཐོསཔ་ཨིན། ཁྱོད་ཀྱིས་ རང་གི་སྐད་ད་ལྟོ་ཡང་མི་ཐོས།',
