  'O Syden nasceu em {data}. Valeu por fazer parte desta história.': "Syden {data} ལུ་སྐྱེས་ཡི། ལོ་རྒྱུས་འདི་གི་ཆ་ཤས་ཅིག་ཨིན་མི་ལུ་ བཀའ་དྲིན་ཆེ།",
