  'Site do Syden': 'Syden གི་ཡོངས་འབྲེལ་ས་ཁོངས།',
  'Só as letras mudam: o resto da tela fica no lugar.': 'ཡིག་འབྲུ་ཚུ་རྐྱངམ་ཅིག་སོར་འོང་། གསལ་གཞི་གི་ལྷག་ལུས་ཚུ་ ས་གནས་ཁར་ལུས་འོང་།',
