  'Sua ideia foi acolhida': 'ཁྱོད་ཀྱི་འཆར་སྣང་ ངོས་ལེན་འབད་ཡི།',
  'Sua internet está segurando a qualidade.': 'ཁྱོད་ཀྱི་ཨིན་ཊར་ནེཊ་གྱིས་ སྤུས་ཚད་ཚད་འཛིན་འབདཝ་ཨིན།',
  'Sua senha, para confirmar que é você': 'ཁྱོད་ཀྱི་ཆོག་ཡིག ཁྱོད་ཨིནམ་ ངེས་དཔྱད་འབད་ནིའི་དོན་ལུ།',
  'Sua transmissão está sem som. O navegador só manda o som se você marcar “compartilhar áudio” na janelinha de escolher a tela.':
    'ཁྱོད་ཀྱི་བརྒྱུད་སྤེལ་ལུ་སྒྲ་མེད། གསལ་གཞི་གདམ་ནིའི་སྒོ་སྒྲིག་ནང་ «སྒྲ་བགོ་བཤའ» ལུ་རྟགས་བཀལ་བ་ཅིན་རྐྱངམ་ཅིག་ བརའུ་ཟར་གྱིས་སྒྲ་གཏངམ་ཨིན།',
  'Sua voz': 'ཁྱོད་ཀྱི་སྐད།',
  'Suba músicas que você já tem. Um arquivo': 'ཁྱོད་ལུ་ཡོད་པའི་གཞས་ཚུ་སྐྱེལ་བཙུགས་འབད།',
  'Suba só o que é seu ou o que você tem direito de usar. Ter o arquivo não é o mesmo que ter direito de tocar para outras pessoas.':
    'ཁྱོད་རའི་ཨིན་མི་ ཡང་ན་ ལག་ལེན་འཐབ་ནིའི་དབང་ཚད་ཡོད་མི་རྐྱངམ་ཅིག་ སྐྱེལ་བཙུགས་འབད། ཡིག་སྣོད་ཡོདཔ་དང་ གཞན་མི་ཚུ་ལུ་གཏང་ནིའི་དབང་ཚད་ཡོདཔ་ གཅིག་མེན།',
