  'Também de graça, e também trocáveis quando quiser. Ficam nas configurações da comunidade, porque valem para a comunidade inteira e não só para você.':
    'རིན་མེད་ཨིན། ནམ་རང་ཡང་སོར་ཚུགས། མི་སྡེའི་སྒྲིག་སྟངས་ནང་ཡོདཔ་ཨིན། ཁྱོད་རྐྱངམ་གཅིག་གི་དོན་ལུ་མེན་པར་ མི་སྡེ་ཧྲིལ་བུམ་གྱི་དོན་ལུ་ཨིན།',
  'Teclas de atalho': 'ལྡེ་སྒྲོམ་གྱི་མགྱོགས་ཐབས།',
