  'Toca um som quando alguém entra ou sai da sua sala, quando alguém começa a compartilhar a tela e quando você silencia ou ensurdece.':
    'མི་ལ་ལོ་ ཁྱོད་ཀྱི་ཁང་མིག་ནང་འཛུལ་བའི་ ཡང་ན་ ཐོན་པའི་སྐབས་ གསལ་གཞི་བགོ་བཤའ་འགོ་བཙུགས་པའི་སྐབས་ ཁྱོད་ཀྱིས་ མའི་ཀོ་ཕོན་ ཡང་ན་ སྒྲ་བཀག་པའི་སྐབས་ སྒྲ་ཅིག་གཏངམ་ཨིན།',
  'Tocando…': 'གཏང་དོ…',
