  'Todas as cores girando devagar. A mais chamativa de todas.': 'ཚོས་གཞི་ཆ་མཉམ་ ག་བུ་ཟུར་འཁོར་བ། མིག་ལུ་ལྷང་ཤོས།',
  'Todo mundo desta comunidade pode usar estes emojis escrevendo {exemplo} ou pelo botão de emoji do chat. Sem assinatura: está tudo liberado.':
    'མི་སྡེ་འདི་གི་མི་ག་ར་གིས་ {exemplo} འབྲི་ཞིནམ་ལས་ ཡང་ན་ ཁ་སླབ་ཀྱི་ཨི་མོ་ཇི་ཨེབ་རྟ་ཐོག་ལས་ ཨི་མོ་ཇི་འདི་ཚུ་ལག་ལེན་འཐབ་ཚུགས། མཁོ་མངགས་མི་དགོ། ཆ་མཉམ་རིན་མེད་ཨིན།',
  'Tom mais alto e mais claro.': 'སྒྲ་གདངས་མཐོ་བ་དང་གསལ་བ།',
  'Tom mais baixo e mais encorpado.': 'སྒྲ་གདངས་དམའ་བ་དང་ལྗིད་ཅན།',
  'Tráfego de saída este mês': 'ཟླཝ་འདི་གི་ཕྱིར་འགྱོ་བའི་གནད་སྡུད།',
  'Tráfego usado da franquia': 'ཚད་ལས་ལག་ལེན་འཐབ་མི་གནད་སྡུད།',
