  'Trocar o e-mail': 'གློག་འཕྲིན་སོར།',
  'Trocar senha': 'ཆོག་ཡིག་སོར།',
  'Tudo aqui é de graça. Escolha o que quiser, troque quando quiser.': 'ནཱ་གི་ཆ་མཉམ་ རིན་མེད་ཨིན། ག་ཅི་དགོ་རུང་གདམ། ནམ་དགོ་རུང་སོར།',
  'Tudo calmo por enquanto. Quando alguém entrar numa chamada, aparece aqui.':
    'ད་ལྟོ་ ག་ནི་ཡང་མེད། མི་ལ་ལོ་ ཁ་པར་ནང་འཛུལ་བ་ཅིན་ ནཱ་ལུ་སྟོན་འོང་།',
  'Turma formada': 'སྡེ་ཚན་ཚང་ཡི།',
  'Última': 'མཇུག་མ།',
  'Últimas 24 horas': 'ཆུ་ཚོད་ ༢༤ ཧེ་མ་ལས་',
  'Últimas quedas': 'མཇུག་གི་ཆད་པ།',
  'último dia para trazer de volta': 'ལོག་ལེན་ནིའི་ཉིན་མཇུག་མ།',
  'Um anel claro e discreto.': 'གསལ་ཞིང་ཞི་བའི་འཁོར་ལོ།',
  'Um anel quente, cor de cobre velho.': 'ཟངས་རྙིང་གི་ཚོས་གཞི་ཅན་གྱི་ དྲོད་ཅན་འཁོར་ལོ།',
  'um canal': 'བརྒྱུད་ལམ་ཅིག',
  'Um dos 25 primeiros': 'དང་པ་ ༢༥ ནང་ལས་གཅིག',
  'Um halo discreto na cor do próprio nome.': 'མིང་རང་གི་ཚོས་གཞི་ནང་ ཞི་བའི་འོད་སྐོར།',
  'Um lugar novo, com canais próprios, e você decide quem entra.': 'རང་སོའི་བརྒྱུད་ལམ་ཅན་གྱི་ ས་གནས་གསརཔ། ག་ནང་འཛུལ་ནི་ཨིན་ན་ ཁྱོད་ཀྱིས་ཐག་གཅོད།',
  'Um lugar novo, com canais próprios. Você escolhe quem entra pelo código de convite.':
    'རང་སོའི་བརྒྱུད་ལམ་ཅན་གྱི་ ས་གནས་གསརཔ། མགྲོན་འབོད་ཨང་རྟགས་ཐོག་ལས་ ག་ནང་འཛུལ་ནི་ཨིན་ན་ ཁྱོད་ཀྱིས་གདམ།',
  'Um pacote instalado entra para toda a comunidade: os emojis dele passam a valer nas mensagens de todo mundo.':
    'གཞི་བཙུགས་འབད་མི་ཐུམ་སྒྲིལ་ མི་སྡེ་ཧྲིལ་བུམ་གྱི་དོན་ལུ་ཨིན། ཁོ་གི་ཨི་མོ་ཇི་ཚུ་ མི་ག་ར་གི་འཕྲིན་ཡིག་ནང་ལཱ་འབདཝ་ཨིན།',
  'Uma cópia do que você escreveu fica 90 dias fora do app, para o caso de pedido de autoridade. Ninguém a lê pelo Syden.':
    'ཁྱོད་ཀྱིས་འབྲི་མི་གི་འདྲ་ཅིག་ ཨེཔ་གི་ཕྱི་ཁར་ ཉིན་ ༩༠ སྲུངམ་ཨིན། དབང་འཛིན་གྱིས་ཞུ་བ་བཀོད་པ་ཅིན་གྱི་དོན་ལུ་ཨིན། Syden ཐོག་ལས་ ག་གིས་ཡང་མི་ལྷག',
  'Uma ideia sua entrou no Syden': 'ཁྱོད་ཀྱི་འཆར་སྣང་ཅིག་ Syden ནང་ཚུད་ཅི།',
  'Uma imagem larga, de 1200 por 300 ou parecida. GIF animado vale, e anima de verdade. Sem capa, fica a arte que você escolheu nas boas-vindas.':
    'པར་རྒྱ་ཅན། 1200 × 300 ཡང་ན་ དེ་བཟུམ། འགུལ་བའི་ GIF ཡང་བཏུབ། ཁ་ཐོག་མེད་པ་ཅིན་ བྱོན་པ་ལེགས་སོའི་དོན་ལུ་གདམ་མི་པར་ལུས་འོང་།',
  'Uma regra ou aviso por linha: o coelho de quem chega lê um por um.':
    'ཐིག་ཕྲེང་རེ་ལུ་ སྒྲིག་གཞི་ ཡང་ན་ བརྡ་ཁྱབ་གཅིག ལྷོད་མི་གི་རི་བོང་གིས་ རེ་རེ་བཞིན་ལྷགཔ་ཨིན།',
  'Usar': 'ལག་ལེན།',
  'Uso do servidor': 'སར་བར་གྱི་ལག་ལེན།',
  'Vale a partir do próximo compartilhamento.': 'བགོ་བཤའ་ཤུལ་མ་ལས་ ནུས་ཅན་འགྱོ།',
  'Vale no app inteiro, só para você.': 'ཨེཔ་ཧྲིལ་བུམ་ནང་ ཁྱོད་རྐྱངམ་གཅིག་གི་དོན་ལུ་ ནུས་ཅན།',
  'Vários de uma vez': 'ཐེངས་གཅིག་ལུ་ མང་པོ།',
  'vazia': 'སྟོངམ།',
  'Veja se o microfone está captando a sua voz.': 'མའི་ཀོ་ཕོན་གྱིས་ ཁྱོད་ཀྱི་སྐད་ཐོབ་དོ་ག་ བལྟ།',
  'Ver mais': 'ཧེང་བལྟ།',
