  'Verde claro.': 'ལྗང་ཁུ་གསལ་བ།',
  'Verde de mato, como a vila.': 'གྲོང་གསེབ་བཟུམ་ རྩྭ་ལྗང་ཁུ།',
  'Verde de pedra.': 'རྡོའི་ལྗང་ཁུ།',
  'Verde escuro.': 'ལྗང་ཁུ་གནག་བ།',
  'Verde fundo com reflexo.': 'འོད་ཅན་གྱི་ལྗང་ཁུ་གཏིང་ཟབ།',
  'Verde-água.': 'ཆུ་ལྗང་ཁུ།',
  'Vermelho fechado.': 'དམརཔོ་གནག་བ།',
  'Vermelho profundo, com pulso.': 'རྩ་འཕར་ཅན་གྱི་ དམརཔོ་གཏིང་ཟབ།',
  'Versalete': 'ཡིག་འབྲུ་ཆེན་པོ་ཆུང་ཀུ།',
