  'Vidro colorido com a luz passando.': 'འོད་འགྱོ་བའི་ ཤེལ་ཚོས་གཞི་ཅན།',
  'Vila': 'གྲོང་གསེབ།',
  'Visitas': 'ལྟ་མི།',
  'Vitral': 'ཤེལ་སྒོ་ཚོས་ཅན།',
  'você': 'ཁྱོད།',
  'Você ainda não está em nenhuma comunidade': 'ཁྱོད་ ད་ལྟོ་ མི་སྡེ་ག་ཅི་ནང་ཡང་མེད།',
  'Você ainda não tem amigos no Syden. A aba': 'Syden ནང་ ཁྱོད་ལུ་ ད་ལྟོ་ཆ་རོགས་མེད། ཤོག་ཁ:',
  'Você ainda não tem este item': 'ཅ་ལ་འདི་ ཁྱོད་ལུ་ད་ལྟོ་མེད།',
  'Você ainda não tem nenhuma. Elas chegam como presente ou como recompensa — por exemplo, quando uma ideia sua entra no Syden.':
    'ཁྱོད་ལུ་ ད་ལྟོ་ག་ནི་ཡང་མེད། གནང་སྐྱེས་ ཡང་ན་ ཆ་རྒྱ་སྦེ་འོངམ་ཨིན — དཔེར་ན་ ཁྱོད་ཀྱི་འཆར་སྣང་ Syden ནང་ཚུད་པའི་སྐབས།',
  'Você chegou no começo de tudo. Obrigado por estar aqui desde quando isto era só uma ideia entre amigos.':
    'ཁྱོད་ ཆ་མཉམ་གྱི་འགོ་ལུ་ལྷོད་ཅི། འདི་ ཆ་རོགས་ཚུ་གི་བར་ན་འཆར་སྣང་རྐྱངམ་ཅིག་ཨིན་པའི་སྐབས་ལས་ ནཱ་ཡོདཔ་ལུ་ བཀྲིན་ཆེ།',
  'Você entrou por um serviço de fora e ainda não tem senha nesta conta. Defina uma aqui: passa a valer como segundo jeito de entrar, e é o que permite desligar aquele serviço depois.':
    'ཁྱོད་ཕྱི་ཁའི་ཞབས་ཏོག་ཐོག་ལས་ནང་བསྐྱོད་འབད་ཡི། རྩིས་ཐོ་འདི་ལུ་ ད་ལྟོ་ཆོག་ཡིག་མེད། ནཱ་ལུ་གཞི་སྒྲིག་འབད། ནང་བསྐྱོད་ཀྱི་ཐབས་ལམ་གཉིས་པ་ཨིན། ཤུལ་ལས་ ཞབས་ཏོག་དེ་ མཐུད་ལམ་བཏོག་ཚུགས།',
  'Você está silenciado!': 'ཁྱོད་ཀྱི་མའི་ཀོ་ཕོན་སྒྲ་བཀག་ཡོདཔ།',
  'Você foi convidado. É só escolher um nome, um e-mail e uma senha.': 'ཁྱོད་ལུ་མགྲོན་འབོད་ཡོདཔ། མིང་དང་ གློག་འཕྲིན་ ཆོག་ཡིག་ གདམ་རྐྱངམ་ཨིན།',
  'Você não bloqueou ninguém.': 'ཁྱོད་ཀྱིས་ ག་ཡང་བཀག་དམ་མ་འབད།',
