  'Tudo o que está na tela. O som do computador vai junto, já sem as vozes desta chamada.': 'གསལ་གཞི་གུ་ཡོད་མི་ཆ་མཉམ། གློག་རིག་གི་སྒྲ་ཡང་མཉམ་དུ་འགྱོ་ ཁ་པར་འདི་གི་སྐད་མ་བཅས་པར།',
