  '{nome} quer jogar. Sente do outro lado!': '{nome} རྩེ་ནི་ལུ་དགའ། ཕར་ཁ་ལུ་སྡོད!',
  'Sua vez!': 'ཁྱོད་ཀྱི་རེས་ཨིན!',
