  '{nome} demorou demais para jogar. {vencedor} venceu!': '{nome} གིས་ ཡུན་རིངམོ་འགོར་ཡི། རྒྱལ་ཁ: {vencedor}!',
  '{nome} desistiu. {vencedor} venceu!': '{nome} གིས་ བཞག་ཡི། རྒྱལ་ཁ: {vencedor}!',
