  'Outros jogos': 'རྩེད་མོ་གཞན།',
  'Stop': 'Stop',
  'Sai uma letra e cada um escreve uma palavra com ela em cada categoria. Quem completar primeiro aperta STOP, e a turma decide o que vale.': 'ཡིག་འབྲུ་ཅིག་ཐོནམ་ད་ མི་རེ་རེ་གིས་ སྡེ་ཚན་རེ་རེ་ནང་ ཡིག་འབྲུ་དེ་གིས་འགོ་བཙུགས་མི་ ཚིག་ཅིག་འབྲིཝ་ཨིན། ཧེ་མ་ཚར་མི་གིས་ STOP ཨེབ་ཞིནམ་ལས་ ཆ་རོགས་ཚུ་གིས་ ག་ཅི་འཐུས་ག་ གྲོས་ཐག་གཅདཔ་ཨིན།',
  'Sudoku': 'Sudoku',
  'Todo mundo recebe o mesmo sudoku, e a sala vê quem está mais perto de terminar.': 'ག་ར་ལུ་ Sudoku གཅིག་མཚུངས་ཐོབ་ཨིན། ཁང་མིག་གིས་ ག་ཚར་ནི་ལུ་ཉེ་ཤོས་ཨིན་ན་ མཐོངམ་ཨིན།',
  'Cinco em linha': 'གྲལ་ཅིག་ལུ་ལྔ།',
  'Duas pessoas põem pedras no tabuleiro, uma de cada vez. Vence quem fizer cinco seguidas. A sala assiste.': 'མི་གཉིས་ཀྱིས་ རེས་མོས་བཞིན་ པང་ལེབ་གུ་ རྡོ་བཞགཔ་ཨིན། གྲལ་ཅིག་ལུ་ ལྔ་བཟོ་མི་ རྒྱལཝ་ཨིན། ཁང་མིག་གིས་ བལྟཝ་ཨིན།',
  'Mancala': 'Mancala',
