  'Pilha': 'གློག་རྫས',
  'Lanterna': 'ལག་གློག',
  'O desenho precisa de pelo menos 2 pessoas na sala.': 'བྲིས་ཏེ་ ཚོད་དཔག་ལུ་ ཁང་མིག་ནང་ མི་ ཉུང་མཐའ་ 2 དགོ།',
  'Agora não é hora de escolher.': 'ད་ལྟོ་ གདམ་ཁ་རྐྱབ་ནིའི་དུས་ཚོད་མེན།',
  'Quem escolhe a palavra é quem vai desenhar.': 'ཚིག་འདི་ བྲི་མི་གིས་ གདམ་དགོ།',
  'Escolha uma das três palavras.': 'ཚིག་གསུམ་ལས་ གཅིག་གདམ།',
  'Agora não é hora de chutar.': 'ད་ལྟོ་ ཚོད་དཔག་རྐྱབ་ནིའི་དུས་ཚོད་མེན།',
  'Quem desenha não chuta.': 'བྲི་མི་གིས་ ཚོད་དཔག་མི་རྐྱབ།',
  'Só quem desenha mexe no desenho.': 'བྲི་མི་རྐྱངམ་ཅིག་གིས་ བྲི་བ་ལུ་ ལག་པ་བཏབ་ཚུགས།',
  'Cargos automáticos': 'རང་བཞིན་ལཱ་འགན།',
  'Crie os cargos da comunidade primeiro, em Membros. Depois volte aqui para entregá-los sozinhos.': 'དང་པ་ མི་སྡེའི་ལཱ་འགན་ཚུ་ འཐུས་མི་ནང་ གསར་བཟོ་འབད། དེ་ལས་ ལཱ་འགན་ཚུ་ རང་བཞིན་གྱིས་ སྤྲོད་ནིའི་དོན་ལུ་ ནཱ་ལུ་ལོག་ཤོག།',
  'Cargo de quem entra': 'གསརཔ་འཛུལ་མིའི་ལཱ་འགན།',
  'Toda pessoa nova recebe estes cargos ao entrar na comunidade.': 'མི་གསརཔ་ག་ར་གིས་ མི་སྡེ་ནང་འཛུལ་བའི་སྐབས་ ལཱ་འགན་འདི་ཚུ་ ཐོབ་འོང་།',
  'Cargos por reação': 'ཚོར་སྣང་གིས་ ལཱ་འགན།',
  'O Syden publica uma mensagem no canal com um emoji para cada cargo. Quem reage ganha o cargo; quem tira a reação, perde.': 'Syden གིས་ བརྒྱུད་ལམ་ནང་ ལཱ་འགན་རེ་རེ་ལུ་ ཨི་མོ་ཇི་རེ་ཡོད་པའི་ འཕྲིན་དོན་ཅིག་ བཙུགས་འོང་། ཚོར་སྣང་བཀོད་མི་གིས་ ལཱ་འགན་ཐོབ་འོང་། ཚོར་སྣང་བཏོན་མི་གིས་ བརླག་འོང་།',
  'Apagar o painel': 'པེ་ནཱལ་ བཏོན་གཏང་།',
  'Escolha os seus cargos reagindo aqui embaixo!': 'འོག་ལུ་ ཚོར་སྣང་བཀོད་དེ་ ཁྱོད་རའི་ལཱ་འགན་ གདམ་ཁ་རྐྱབ།',
  'Texto do painel': 'པེ་ནཱལ་གྱི་ཡིག་ཆ།',
  'Emoji {n}': 'ཨི་མོ་ཇི་ {n}',
  'Cargo {n}': 'ལཱ་འགན་ {n}',
  'Mais um emoji': 'ཨི་མོ་ཇི་ གཞན་ཅིག།',
