  'Quais jogos a turma joga, com quantas pessoas e quantas partidas vão até o fim. Só contagem: respostas e desenhos não são guardados. Conta a partir de 12/10/2026.': 'སྡེ་ཚན་གྱིས་ རྩེད་མོ་ག་ཅི་ཚུ་ རྩེདཔ་ཨིན་ན་ མི་ག་དེམ་ཅིག་གིས་ དང་ རྩེད་འགྲན་ག་དེམ་ཅིག་ མཇུག་ཚུན་ཚོད་ རྩེདཔ་ཨིན་ན། གྱངས་ཁ་རྐྱངམ་ཅིག། ལན་དང་ རི་མོ་ཚུ་ མི་བཞག། 12/10/2026 ལས་ཚུར་ གྱངས་ཁ་རྐྱབ་ཨིན།',
