  '{tipo} «{item}» ({onde}) saiu do Syden porque {quem} disse ter os direitos. Se você tinha autorização para publicar, responda aqui contando: a sua resposta vai ser levada em conta. Enquanto isso não ficar claro, fica fora. Os termos explicam como funciona, na seção 4: https://syden.chat/termos.html#direito-autoral': '{tipo} «{item}» ({onde}) Syden ནང་ལས་ བཏོན་ཡོདཔ་ཨིན། ག་ཅི་སྨོ་ཟེར་བ་ཅིན་ {quem} གིས་ དབང་ཆ་ ང་བཅས་ལུ་ཡོད་ཟེར་ཡི། ཁྱོད་ལུ་ བཙུགས་ནིའི་ གནང་བ་ཡོད་པ་ཅིན་ ནཱ་ལུ་ ལན་བཏབ་སྟེ་ གསལ་བཤད་འབད། ཁྱོད་ཀྱི་ལན་ ཆ་འཇོག་འབད་འོང་། འདི་ གསལ་ཏོག་ཏོ་མ་ཐོན་ཚུན་ ནང་དོན་འདི་ བཏོན་ཏེ་རང་ སྡོད་འོང་། ག་དེ་སྦེ་ལཱ་འབདཝ་ཨིན་ན་ ཆ་རྐྱེན་གྱི་དབྱེ་ཚན་ 4 ནང་ གསལ་བཤད་འབད་དེ་ཡོད: https://syden.chat/termos.html#direito-autoral',
  '«{nome}» saiu.': '«{nome}» བཏོན་ཡོད།',
  'Saíram junto {n} cópia(s) do mesmo arquivo.': 'ཡིག་སྣོད་གཅིག་པའི་ འདྲ་བཤུས་ མཉམ་སྦེ་ བཏོན་ཡོདཔ: {n}',
  'Quem subiu recebeu o aviso numa conversa com você.': 'སྐྱེལ་བཙུགས་འབད་མི་ལུ་ ཁྱོད་དང་གཅིག་ཁར་ གཏམ་གླེང་ནང་ བརྡ་བསྐུལ་ཐོབ་ཡི།',
  'Não havia a quem avisar.': 'བརྡ་བསྐུལ་འབད་ནི་ ཨ་ནཱ་ག་ཡང་ མེད།',
  'É a retirada número {n} desta pessoa.': 'འདི་ མི་འདི་གི་ བཏོན་ཐེངས་ {n} པ་ཨིན།',
  'Direito autoral': 'རྩོམ་པ་པོའི་དབང་ཆ།',
  'Quem tem o direito escreve para direitos@syden.chat dizendo o que é e onde está. Procure pelo nome, retire, e quem subiu recebe o aviso numa conversa com você, onde pode contestar.': 'དབང་ཆ་ཡོད་མི་གིས་ ག་ཅི་ཨིན་ན་དང་ ག་ཏེ་ཡོདཔ་ཨིན་ན་ direitos@syden.chat ལུ་ འབྲི་འོང་། མིང་གིས་ འཚོལ། བཏོན། དེ་ལས་ སྐྱེལ་བཙུགས་འབད་མི་ལུ་ ཁྱོད་དང་གཅིག་ཁར་ གཏམ་གླེང་ནང་ བརྡ་བསྐུལ་ཐོབ་འོང་། དེ་ནང་ ངོ་རྒོལ་འབད་ཚུགས།',
  'Nome do som, da música, do emoji ou do arquivo': 'སྒྲ་ དང་ གཞས་ ཨི་མོ་ཇི་ ཡང་ན་ ཡིག་སྣོད་ཀྱི་མིང་།',
