  'Reclamação de {quem}. Quem retirou: {por}.': 'ངོ་རྒོལ: {quem}། བཏོན་མི: {por}།',
  'Tickets': 'ཊི་ཀེཊ།',
  'Quem precisa falar com a administração abre um ticket no início da comunidade, com um assunto. Ele vira uma conversa privada em grupo entre essa pessoa e quem administra, e aparece na lista de conversas de vocês.': 'འཛིན་སྐྱོང་པ་ཚུ་དང་ གཏམ་བཤད་དགོ་མི་གིས་ མི་སྡེའི་འགོ་ཤོག་ནང་ དོན་ཚན་ཅིག་དང་གཅིག་ཁར་ ཊི་ཀེཊ་ཅིག་ ཁ་ཕྱེ་འོང་། དེ་ མི་དེ་དང་ འཛིན་སྐྱོང་པ་ཚུ་གི་བར་ན་ སྒེར་གྱི་སྡེ་ཚན་གཏམ་གླེང་ལུ་ འགྱུར་ཏེ་ ཁྱེད་ཚུ་གི་ གཏམ་གླེང་ཐོ་ཡིག་ནང་ མཐོང་འོང་།',
  'Deixar os membros abrirem tickets': 'འཐུས་མི་ཚུ་ལུ་ ཊི་ཀེཊ་ཁ་ཕྱེ་བཅུག།',
  'Abertos': 'ཁ་ཕྱེ་ཡོདཔ།',
  'Nenhum ticket aberto.': 'ཁ་ཕྱེ་ཡོད་པའི་ ཊི་ཀེཊ་མེད།',
