  'Esta comunidade não usa tickets.': 'མི་སྡེ་འདི་གིས་ ཊི་ཀེཊ་ལག་ལེན་མི་འཐབ།',
  'Diga em poucas palavras qual é o assunto.': 'དོན་ཚན་ ག་ཅི་ཨིན་ན་ ཚིག་ཉུང་ཤོས་ཅིག་ནང་ སླབ།',
  'Ainda não há quem atenda os tickets nesta comunidade.': 'མི་སྡེ་འདི་ནང་ ཊི་ཀེཊ་ལུ་ ལན་སྤྲོད་མི་ ད་ལྟོ་ཚུན་ མེད།',
  'Ticket não encontrado.': 'ཊི་ཀེཊ་ མ་ཐོབ།',
  'Só quem abriu o ticket ou quem administra pode encerrá-lo.': 'ཊི་ཀེཊ་ཁ་ཕྱེ་མི་ ཡང་ན་ འཛིན་སྐྱོང་པ་རྐྱངམ་ཅིག་གིས་ ཁ་བསྡམ་ཚུགས།',
  'Só quem administra a comunidade mexe nos cargos automáticos.': 'མི་སྡེའི་འཛིན་སྐྱོང་པ་ཚུ་རྐྱངམ་ཅིག་གིས་ རང་བཞིན་ལཱ་འགན་ སོར་ཚུགས།',
  'Escolha um canal de texto da comunidade.': 'མི་སྡེའི་ ཡིག་འབྲུའི་བརྒྱུད་ལམ་ཅིག་ གདམ།',
