  'Painel não encontrado.': 'པེ་ནཱལ་ མ་ཐོབ།',
  'E-mail confirmado. Agora dá para recuperar a sua senha por ele.': 'གློག་འཕྲིན་ངེས་གཏན་བཟོ་ཡི། ད་ ཆོག་ཡིག་འདི་ གློག་འཕྲིན་ཐོག་ལས་ སླར་ལོག་ལེན་ཚུགས།',
  'A resposta veio sem a sua conta. Tente de novo.': 'ལན་འདི་ ཁྱོད་ཀྱི་རྩིས་ཐོ་མེད་པར་འོང་ཡི། ལོག་འབད།',
  'Conta do {provedor} ligada. Agora dá para entrar por ela.': 'རྩིས་ཐོ་མཐུད་ཡི: {provedor}། ད་ འདི་ཐོག་ལས་ནང་བསྐྱོད་འབད་ཚུགས།',
  'Fechar aviso': 'བརྡ་བསྐུལ་ཁ་བསྡམས།',
  'Entrar com {provedor}': 'འདི་ཐོག་ལས་ནང་བསྐྱོད: {provedor}',
