  'Não chegou em alguns minutos? Dê uma olhada no spam ou nas promoções. Se não estiver lá, mande de novo.': 'སྐར་མ་ཁ་ཙམ་ནང་མ་འོང་ག? spam ཡང་ན་ ཚོང་བསྒྲགས་ནང་བལྟ། དེ་ནང་ཡང་མེད་པ་ཅིན་ ལོག་གཏང་།',
