  '1 emoji entrou. Ficaram de fora, porque a comunidade já tem esses nomes: {nomes}': 'ཨི་མོ་ཇི་ ༡ ཚུད་ཡི། མི་སྡེ་ནང་ མིང་འདི་ཚུ་ཧེ་མ་ལས་ཡོདཔ་ལས་ མ་ཚུད་མི: {nomes}',
  '{n} emojis entraram. Ficaram de fora, porque a comunidade já tem esses nomes: {nomes}': 'ཨི་མོ་ཇི་ {n} ཚུད་ཡི། མི་སྡེ་ནང་ མིང་འདི་ཚུ་ཧེ་མ་ལས་ཡོདཔ་ལས་ མ་ཚུད་མི: {nomes}',
  'Pronto: 1 emoji entrou em {comunidade}.': 'ཚར་ཡི: ཨི་མོ་ཇི་ ༡ ཚུད་ཡི། མི་སྡེ: {comunidade}',
  'Pronto: {n} emojis entraram em {comunidade}.': 'ཚར་ཡི: ཨི་མོ་ཇི་ {n} ཚུད་ཡི། མི་སྡེ: {comunidade}',
  'Emoji acrescentado — quem já tem o pacote recebeu na hora.': 'ཨི་མོ་ཇི་ཁ་སྐོང་འབད་ཡི། ཐུམ་སྒྲིལ་ཡོད་མི་ཚུ་ལུ་ ད་ལྟོ་ར་འཐོབ་ཅི།',
  '{n} emojis acrescentados — quem já tem o pacote recebeu na hora.': 'ཨི་མོ་ཇི་ {n} ཁ་སྐོང་འབད་ཡི། ཐུམ་སྒྲིལ་ཡོད་མི་ཚུ་ལུ་ ད་ལྟོ་ར་འཐོབ་ཅི།',
  'Emoji acrescentado ao pacote.': 'ཐུམ་སྒྲིལ་ནང་ ཨི་མོ་ཇི་ཁ་སྐོང་འབད་ཡི།',
  '{n} emojis acrescentados ao pacote.': 'ཐུམ་སྒྲིལ་ནང་ ཨི་མོ་ཇི་ {n} ཁ་སྐོང་འབད་ཡི།',
