  'PNG, JPG, GIF ou WEBP; cada um vira um quadradinho de 128 pixels. No máximo {n} emojis por pacote.': 'PNG, JPG, GIF ཡང་ན་ WEBP། རེ་རེ་ 128 པིག་སེལ་གྱི་ གྲུ་བཞི་ཆུང་ཀུ་ཅིག་ལུ་འགྱུར་འོང་། ཐུམ་སྒྲིལ་རེ་ལུ་ ཨི་མོ་ཇི་ {n} ཚུན།',
  'Nome do emoji {n}': 'ཨི་མོ་ཇི་ {n} གི་མིང་།',
