  'Criar pacote com 1 emoji': 'ཨི་མོ་ཇི་ ༡ གིས་ ཐུམ་སྒྲིལ་བཟོ།',
  'Criar pacote com {n} emojis': 'ཨི་མོ་ཇི་ {n} གིས་ ཐུམ་སྒྲིལ་བཟོ།',
  'Emojis de {comunidade}': 'ཨི་མོ་ཇི་ཚུ: {comunidade}',
  'Junta todos os emojis que {comunidade} tem hoje num pacote só, para as suas outras comunidades (ou as dos seus amigos) instalarem de uma vez.': 'ད་ལྟོ་ཡོད་པའི་ཨི་མོ་ཇི་ཆ་མཉམ་ ཐུམ་སྒྲིལ་གཅིག་ནང་བསྡུ་སྟེ་ ཁྱོད་ཀྱི་མི་སྡེ་གཞན་ཚུ་ (ཡང་ན་ ཆ་རོགས་ཀྱི་མི་སྡེ་ཚུ་) གིས་ ཚར་གཅིག་ལུ་གཞི་བཙུགས་ཚུགས། མི་སྡེ: {comunidade}',
