  'Pacotes de emoji': 'ཨི་མོ་ཇི་གི་ཐུམ་སྒྲིལ་ཚུ།',
  'Criar pacote': 'ཐུམ་སྒྲིལ་བཟོ།',
  'Publicar os daqui': 'ནཱ་གི་ཚུ་དཔར་བསྐྲུན་འབད།',
  'Nenhum emoji com "{busca}".': '"{busca}" ཡོད་པའི་ཨི་མོ་ཇི་མེད།',
