  'Uma comunidade é um lugar com canais de texto e salas de voz, como um servidor do Discord. Entre na de um amigo com o código de convite dele, ou crie a sua.': 'མི་སྡེ་ཟེར་མི་འདི་ ཡིག་འབྲུའི་བརྒྱུད་ལམ་དང་ སྐད་ཀྱི་ཁང་མིག་ཡོད་སའི་ས་ཁོངས་ཅིག་ཨིན། Discord གི་སར་བར་བཟུམ། ཆ་རོགས་ཀྱི་མགྲོན་འབོད་ཨང་རྟགས་ཐོག་ལས་ མི་སྡེ་དེ་ནང་འཛུལ། ཡང་ན་ ཁྱོད་རང་གི་བཟོ།',
  'Ligue a sua conta do Google, Discord, GitHub ou Steam para entrar no Syden por lá, sem digitar senha. Dá para ligar mais de um, e todos levam a esta mesma conta.': 'Google, Discord, GitHub ཡང་ན་ Steam གི་རྩིས་ཐོ་མཐུད་དེ་ ཆོག་ཡིག་མ་བཙུགས་པར་ Syden ནང་ནང་བསྐྱོད་འབད། གཅིག་ལས་ལྷག་སྟེ་མཐུད་ཚུགས་ ཆ་མཉམ་ རྩིས་ཐོ་འདི་རང་ལུ་འོང་།',
  'Ligado a esta conta': 'རྩིས་ཐོ་འདི་ལུ་མཐུད་ཡོད།',
