  'Desfazer amizade': 'ཆ་རོགས་ཀྱི་འབྲེལ་བ་བཏོག',
  'mostra quem divide comunidade com você.': 'ནང་ ཁྱོད་དང་མི་སྡེ་གཅིག་ཁར་ཡོད་མི་ཚུ་སྟོནམ་ཨིན།',
