  'Precisa ser o nome exato — o Syden não lista contas por pedaços de nome, para ninguém conseguir descobrir quem existe aqui dentro.': 'མིང་ཏག་ཏག་ཨིན་དགོ — ནཱ་ལུ་ག་ཡོདཔ་ཨིན་ན་ མི་གཅིག་གིས་ཡང་ མ་ཤེས་ནིའི་དོན་ལུ་ Syden གིས་ མིང་གི་ཆ་ཤས་ཐོག་ལས་ རྩིས་ཐོ་ཚུ་ཐོ་མི་བཀོད།',
