  'A partida ainda não começou.': 'རྩེད་མོ་ ད་ལྟོ་ཡང་ འགོ་མ་བཙུགས་པས།',
  'A partida já começou.': 'རྩེད་མོ་ ཧེ་མ་ལས་ར་ འགོ་བཙུགས་ཡི།',
  'Só quem começou dá a largada.': 'མགྲོན་བརྡ་བཏང་མི་ རྐྱངམ་ཅིག་གིས་ རྩེད་མོ་ འགོ་བཙུགས་ཚུགས།',
  'Ainda falta gente para começar.': 'འགོ་བཙུགས་ནི་ལུ་ མི་ ད་ལྟོ་ཡང་ མ་ལང་པས།',
  'Você está assistindo. Dá para entrar na próxima partida.': 'ཁྱོད་ བལྟ་དོ་ཡོདཔ། ཤུལ་མམ་གྱི་ རྩེད་མོ་ནང་ འཛུལ་ཚུགས།',
