  'Enviar esta imagem junto (só quem cuida do Syden vê)': 'པར་འདི་ཡང་མཉམ་སྦེ་གཏང་། (Syden ལུ་ལྟ་རྟོག་འབད་མི་རྐྱངམ་ཅིག་གིས་མཐོང་།)',
